package com.casystem.onboarding.controller;
import com.casystem.onboarding.model.*;import com.casystem.onboarding.repository.*;import com.casystem.onboarding.service.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") @CrossOrigin(origins="*") public class AdminController{private final UserRepository users;private final DocumentRepository docs;private final AuditLogRepository logs;private final TokenService tokens;private final CryptoService crypto;private final AuditService audit;private final MailSettingsRepository mailSettings;private final MailService mailService;private final org.springframework.security.crypto.password.PasswordEncoder encoder;public AdminController(UserRepository u,DocumentRepository d,AuditLogRepository l,TokenService t,CryptoService c,AuditService a,MailSettingsRepository ms,MailService mail,org.springframework.security.crypto.password.PasswordEncoder e){users=u;docs=d;logs=l;tokens=t;crypto=c;audit=a;mailSettings=ms;mailService=mail;encoder=e;}private User admin(String h){Long id=tokens.userId(h);User u=users.findById(id).orElseThrow();if(!"ADMIN".equals(u.getRole()))throw new SecurityException("Acceso exclusivo para administrador");return u;}private String dec(String s){if(s==null||s.isBlank())return "";try{return crypto.decrypt(s);}catch(Exception e){return s;}}@GetMapping("/users")public List<Map<String,Object>> list(@RequestHeader("Authorization")String h,HttpServletRequest r){User a=admin(h);audit.log(a.getId(),"ADMIN_LIST_USERS",r.getRemoteAddr());return users.findAll().stream().filter(u->!u.isDeleted()&&!"ADMIN".equals(u.getRole())).map(u->Map.<String,Object>of("id",u.getId(),"name",u.getName()==null?"":u.getName(),"email",u.getEmail(),"phone",dec(u.getPhone()),"address",dec(u.getAddress()),"municipality",dec(u.getMunicipality()),"state",dec(u.getState()),"documents",docs.findByUserIdAndDeletedFalseOrderByCreatedAtDesc(u.getId()).size())).toList();}@GetMapping("/users/{id}")public Map<String,Object> one(@RequestHeader("Authorization")String h,@PathVariable Long id,HttpServletRequest r){User a=admin(h),u=users.findById(id).orElseThrow();audit.log(a.getId(),"ADMIN_VIEW_USER:"+id,r.getRemoteAddr());Map<String,Object>m=new LinkedHashMap<>();m.put("id",u.getId());m.put("name",u.getName());m.put("email",u.getEmail());m.put("phone",dec(u.getPhone()));m.put("address",dec(u.getAddress()));m.put("postalCode",dec(u.getPostalCode()));m.put("settlement",dec(u.getSettlement()));m.put("municipality",dec(u.getMunicipality()));m.put("state",dec(u.getState()));m.put("documentNumber",dec(u.getDocumentNumber()));m.put("documents",docs.findByUserIdAndDeletedFalseOrderByCreatedAtDesc(id).stream().map(d->Map.of("id",d.getId(),"fileName",d.getFileName(),"contentType",d.getContentType(),"createdAt",d.getCreatedAt())).toList());return m;}@GetMapping("/documents/{id}")public ResponseEntity<byte[]> doc(@RequestHeader("Authorization")String h,@PathVariable Long id,HttpServletRequest r){User a=admin(h);Document d=docs.findById(id).filter(x->!x.isDeleted()).orElseThrow();audit.log(a.getId(),"ADMIN_VIEW_DOCUMENT:"+id,r.getRemoteAddr());return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+d.getFileName().replace("\"","")+"\"").contentType(MediaType.parseMediaType(d.getContentType())).body(crypto.decryptBytes(d.getEncryptedContent()));}@GetMapping("/stats")public Map<String,Object> stats(@RequestHeader("Authorization")String h,HttpServletRequest r){User a=admin(h);audit.log(a.getId(),"ADMIN_VIEW_DASHBOARD",r.getRemoteAddr());var us=users.findAll().stream().filter(u->!u.isDeleted()&&!"ADMIN".equalsIgnoreCase(u.getRole())).toList();long dc=us.stream().mapToLong(u->docs.findByUserIdAndDeletedFalseOrderByCreatedAtDesc(u.getId()).size()).sum();Map<String,Long> byState=new LinkedHashMap<>();for(User u:us){String state=dec(u.getState());if(!state.isBlank())byState.merge(state,1L,Long::sum);}long completed=us.stream().filter(u->!dec(u.getAddress()).isBlank()&&!dec(u.getState()).isBlank()&&!docs.findByUserIdAndDeletedFalseOrderByCreatedAtDesc(u.getId()).isEmpty()).count();Map<String,Object> out=new LinkedHashMap<>();out.put("users",us.size());out.put("documents",dc);out.put("completed",completed);out.put("pending",Math.max(0,us.size()-completed));out.put("usersByState",byState);return out;}
@GetMapping("/activity")public List<Map<String,Object>> activity(@RequestHeader("Authorization")String h){admin(h);return logs.findTop50ByOrderByCreatedAtDesc().stream().map(l->{Map<String,Object>m=new LinkedHashMap<>();m.put("id",l.getId());m.put("userId",l.getUserId());m.put("action",l.getAction());m.put("ip",l.getIp());m.put("createdAt",l.getCreatedAt());return m;}).toList();}

@GetMapping("/mail-settings") public Map<String,Object> mailSettings(@RequestHeader("Authorization")String h){admin(h);MailSettings s=mailSettings.findById(1).orElse(new MailSettings());Map<String,Object>m=new LinkedHashMap<>();m.put("provider",s.getProvider());m.put("senderEmail",s.getSenderEmail()==null?"":s.getSenderEmail());m.put("host",s.getHost());m.put("port",s.getPort());m.put("auth",s.isAuth());m.put("starttls",s.isStarttls());m.put("passwordConfigured",s.getEncryptedPassword()!=null&&!s.getEncryptedPassword().isBlank());return m;}
@PostMapping("/mail-settings") public Map<String,Object> saveMail(@RequestHeader("Authorization")String h,@RequestBody Map<String,Object>b,HttpServletRequest r){User a=admin(h);MailSettings s=mailSettings.findById(1).orElse(new MailSettings());s.setId(1);s.setProvider(String.valueOf(b.getOrDefault("provider","Gmail")));s.setSenderEmail(String.valueOf(b.getOrDefault("senderEmail","" )).trim());s.setHost(String.valueOf(b.getOrDefault("host","smtp.gmail.com" )).trim());s.setPort(Integer.parseInt(String.valueOf(b.getOrDefault("port",587))));s.setAuth(Boolean.parseBoolean(String.valueOf(b.getOrDefault("auth",true))));s.setStarttls(Boolean.parseBoolean(String.valueOf(b.getOrDefault("starttls",true))));String pass=String.valueOf(b.getOrDefault("password",""));if(!pass.isBlank())s.setEncryptedPassword(crypto.encrypt(pass.replace(" ","")));mailSettings.save(s);audit.log(a.getId(),"ADMIN_SMTP_UPDATED",r.getRemoteAddr());return Map.of("ok",true);}
@PostMapping("/mail-settings/test") public Map<String,Object> testMail(@RequestHeader("Authorization")String h,@RequestBody Map<String,Object>b,HttpServletRequest r){User a=admin(h);MailSettings s=mailSettings.findById(1).orElse(new MailSettings());String pass=String.valueOf(b.getOrDefault("password",""));if(!pass.isBlank())s.setEncryptedPassword(crypto.encrypt(pass.replace(" ","")));if(b.get("senderEmail")!=null)s.setSenderEmail(String.valueOf(b.get("senderEmail")));if(b.get("host")!=null)s.setHost(String.valueOf(b.get("host")));if(b.get("port")!=null)s.setPort(Integer.parseInt(String.valueOf(b.get("port"))));String to=String.valueOf(b.getOrDefault("testEmail","")).trim();if(to.isBlank())throw new IllegalArgumentException("Captura un correo para prueba.");mailService.test(s,to);audit.log(a.getId(),"ADMIN_SMTP_TEST",r.getRemoteAddr());return Map.of("ok",true,"message","Correo de prueba enviado a "+to);}
@PostMapping("/admins") public Map<String,Object> createAdmin(@RequestHeader("Authorization")String h,@RequestBody Map<String,String>b,HttpServletRequest r){User a=admin(h);String email=b.getOrDefault("email","").trim().toLowerCase();if(email.isBlank()||users.findByEmailAndDeletedFalse(email).isPresent())throw new IllegalArgumentException("Correo inválido o ya registrado");User u=new User();u.setEmail(email);u.setName(b.getOrDefault("name","Administrador"));u.setPassword(encoder.encode(b.getOrDefault("password","Admin2026!")));u.setRole("ADMIN");users.save(u);audit.log(a.getId(),"ADMIN_CREATED:"+u.getId(),r.getRemoteAddr());return Map.of("id",u.getId(),"email",u.getEmail(),"name",u.getName());}
@GetMapping("/admins") public List<Map<String,Object>> admins(@RequestHeader("Authorization")String h){admin(h);return users.findAll().stream().filter(u->!u.isDeleted()&&"ADMIN".equals(u.getRole())).map(u->Map.<String,Object>of("id",u.getId(),"name",u.getName(),"email",u.getEmail())).toList();}
@PutMapping("/profile") public Map<String,Object> adminProfile(@RequestHeader("Authorization")String h,@RequestBody Map<String,String>b,HttpServletRequest r){User a=admin(h);String name=b.getOrDefault("name",a.getName()).trim();if(name.length()<2)throw new IllegalArgumentException("Nombre inválido");a.setName(name);String np=b.getOrDefault("newPassword","");if(!np.isBlank()){if(np.length()<8)throw new IllegalArgumentException("La contraseña debe tener al menos 8 caracteres");a.setPassword(encoder.encode(np));}users.save(a);audit.log(a.getId(),"ADMIN_PROFILE_UPDATED",r.getRemoteAddr());return Map.of("ok",true,"name",a.getName());}
}